window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-aa584d5e668ba82a"]={"versions": [{"id": "FIG-aa584d5e668ba82a", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm (<code>ad Bootloader</code>) im Kontext des AUTOSAR ECU State Managers (EcuM). Es visualisiert den grundlegenden Verzweigungsablauf zur Ermittlung und Ansteuerung des Boot-Ziels nach einem System-Reset vor dem Übergang in die eigentliche Anwendungs- oder Bootloader-Ausführung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst:</p>\n<ul class=\"fig-list\">\n<li>Initialer Startknoten: <code>Reset</code> (Hard-/Software-Reset des Steuergeräts).</li>\n<li>Aktionen / Zustände:</li>\n<li><code>Boot Menu</code>: Auswerte- und Entscheidungslogik zur Bestimmung des Startziels.</li>\n<li><code>Bootloader</code>: Zielzustand für Reprogrammierungs- und Flash-Aktivitäten.</li>\n<li><code>Application</code>: Zielzustand für die reguläre Ausführung des AUTOSAR-Basissoftware- und Anwendungsstacks.</li>\n<li>Kontrollknoten: Verzweigungsknoten (Decision Node) <code>Boot Target</code>.</li>\n<li>Kontrollflüsse: Gerichtete Kanten von <code>Reset</code> zu <code>Boot Menu</code>, von <code>Boot Menu</code> zu <code>Boot Target</code> sowie verzweigende Pfade zu <code>Bootloader</code> und <code>Application</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Ein System-Reset (<code>Reset</code>) löst den Kontrollfluss aus.</li>\n<li>Der Ablauf führt in das <code>Boot Menu</code>, in dem die Boot-Konfiguration und persistierte Boot-Flags ausgewertet werden.</li>\n<li>Am Entscheidungsknoten <code>Boot Target</code> teilt sich der Pfad auf:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Verzweigung in den <code>Bootloader</code>, falls ein Reprogrammierungs- oder Wartungsziel angefordert ist.</li>\n<li>Verzweigung in die <code>Application</code>, falls der reguläre Betrieb der ECU gestartet werden soll.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm beschreibt die funktionale Trennung zwischen Bootloader und AUTOSAR-Laufzeitumgebung. Der EcuM muss Schnittstellen zur Abfrage und zum Setzen des Boot-Ziels (<code>EcuM_GetBootTarget</code>, <code>EcuM_SelectBootTarget</code>) bereitstellen, welche die Transitionen nach einem Reset steuern. Integratoren müssen sicherstellen, dass die im <code>Boot Menu</code> ausgewerteten Flags (z. B. im NVRAM oder uninitialisierten RAM) konsistent zwischen Bootloader und EcuM ausgetauscht werden.</p>"}, {"id": "FIG-11e7dc1171c6c1e4", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm (<code>ad Bootloader</code>) im Kontext des AUTOSAR ECU State Managers (EcuM). Es visualisiert den grundlegenden Verzweigungsablauf zur Ermittlung und Ansteuerung des Boot-Ziels nach einem System-Reset vor dem Übergang in die eigentliche Anwendungs- oder Bootloader-Ausführung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst:</p>\n<ul class=\"fig-list\">\n<li>Initialer Startknoten: <code>Reset</code> (Hard-/Software-Reset des Steuergeräts).</li>\n<li>Aktionen / Zustände:</li>\n<li><code>Boot Menu</code>: Auswerte- und Entscheidungslogik zur Bestimmung des Startziels.</li>\n<li><code>Bootloader</code>: Zielzustand für Reprogrammierungs- und Flash-Aktivitäten.</li>\n<li><code>Application</code>: Zielzustand für die reguläre Ausführung des AUTOSAR-Basissoftware- und Anwendungsstacks.</li>\n<li>Kontrollknoten: Verzweigungsknoten (Decision Node) <code>Boot Target</code>.</li>\n<li>Kontrollflüsse: Gerichtete Kanten von <code>Reset</code> zu <code>Boot Menu</code>, von <code>Boot Menu</code> zu <code>Boot Target</code> sowie verzweigende Pfade zu <code>Bootloader</code> und <code>Application</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Ein System-Reset (<code>Reset</code>) löst den Kontrollfluss aus.</li>\n<li>Der Ablauf führt in das <code>Boot Menu</code>, in dem die Boot-Konfiguration und persistierte Boot-Flags ausgewertet werden.</li>\n<li>Am Entscheidungsknoten <code>Boot Target</code> teilt sich der Pfad auf:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Verzweigung in den <code>Bootloader</code>, falls ein Reprogrammierungs- oder Wartungsziel angefordert ist.</li>\n<li>Verzweigung in die <code>Application</code>, falls der reguläre Betrieb der ECU gestartet werden soll.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm beschreibt die funktionale Trennung zwischen Bootloader und AUTOSAR-Laufzeitumgebung. Der EcuM muss Schnittstellen zur Abfrage und zum Setzen des Boot-Ziels (<code>EcuM_GetBootTarget</code>, <code>EcuM_SelectBootTarget</code>) bereitstellen, welche die Transitionen nach einem Reset steuern. Integratoren müssen sicherstellen, dass die im <code>Boot Menu</code> ausgewerteten Flags (z. B. im NVRAM oder uninitialisierten RAM) konsistent zwischen Bootloader und EcuM ausgetauscht werden.</p>"}], "trans": [{"from": "FIG-aa584d5e668ba82a", "to": "FIG-11e7dc1171c6c1e4", "fr": "R2.1.20", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
